WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area FROM `basedosdados.br_sfb_sicar.area_imovel` a JOIN mun USING(id_municipio) WHERE a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),d AS (SELECT DISTINCT p.ano_emissao,p.id_referencia_bacen,p.id_car_norm,c.id_municipio,COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) documento FROM p JOIN car c ON c.id_car_norm=p.id_car_norm WHERE c.area<0.1 AND COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) IS NOT NULL),by_doc AS (SELECT id_municipio,documento,COUNT(DISTINCT id_car_norm) imoveis_por_mutuario FROM d GROUP BY 1,2),by_car AS (SELECT id_municipio,id_car_norm,COUNT(DISTINCT documento) mutuarios_por_imovel FROM d GROUP BY 1,2),s AS (SELECT id_municipio,COUNT(DISTINCT documento) mutuarios,COUNT(DISTINCT id_car_norm) imoveis_micro FROM d GROUP BY 1) SELECT s.id_municipio,s.mutuarios,s.imoveis_micro,COUNTIF(x.imoveis_por_mutuario>1) mutuarios_com_varios_imoveis,MAX(x.imoveis_por_mutuario) max_imoveis_por_mutuario,COUNTIF(y.mutuarios_por_imovel>1) imoveis_com_varios_mutuarios,MAX(y.mutuarios_por_imovel) max_mutuarios_por_imovel FROM s JOIN by_doc x USING(id_municipio) JOIN by_car y USING(id_municipio) GROUP BY 1,2,3 ORDER BY 1